import{_ as r,a,b as o,c as l}from"./chunks/893fda8bb771e8b7e819.DQcukAyh.js";import{_ as i,C as s,o as n,c as h,j as p,a as c,E as u,a6 as f}from"./chunks/framework.CnPv4DE1.js";const N=JSON.parse('{"title":"如何从生活中得到你想要的","description":"","frontmatter":{"title":"如何从生活中得到你想要的","originalTitle":"How To Get What You Want Out Of Life","date":"2022-08-28","originalUrl":"https://thedankoe.com/letters/how-to-get-what-you-want-out-of-life/","minutes":8,"sourceHash":"ccec8c67b8f184cb23ceba40cde5cb72799927687c50aaf24e7b5dd23055223d","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-get-what-you-want-out-of-life/"}]]},"headers":[],"relativePath":"letters/how-to-get-what-you-want-out-of-life.md","filePath":"letters/how-to-get-what-you-want-out-of-life.md"}'),m={name:"letters/how-to-get-what-you-want-out-of-life.md"};function _(b,e,d,w,k,g){const t=s("ArticleMeta");return n(),h("div",null,[e[0]||(e[0]=p("h1",{id:"如何从生活中得到你想要的",tabindex:"-1"},[c("如何从生活中得到你想要的 "),p("a",{class:"header-anchor",href:"#如何从生活中得到你想要的","aria-label":'Permalink to "如何从生活中得到你想要的"'},"​")],-1)),u(t),e[1]||(e[1]=f('<p><a href="https://www.youtube.com/embed/gCYfNTagJf8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>现代教育系统在一件事上非常在行：</p><p><em>把人们训练去从事可被轻易替代的工作。</em></p><p>这是我在上大学前就有的顿悟。我知道即使我去上了大学，为自己找到合适职业这件事，在毕业时也远未结束。</p><p>如果我想赚到足够多的钱，从而消除由钱引发的各种问题，我有两个选择：</p><p>选择一：</p><ul><li>攀爬职场阶梯</li><li>用我的技能去建设别人的企业</li><li>牺牲我的欲望和时间，换取更高的薪水</li></ul><p>选择二：</p><ul><li>打造我自己的阶梯</li><li>用我的技能去建设我自己的企业</li><li>牺牲我的空闲时间，为实现目标积累杠杆</li></ul><p>当然，我这里说得有点夸张了。</p><p>我已经自雇了3到4年，我现在对大多数事情<em>极度</em>脱节。我对企业打工有一种扭曲的认知，而且我对此心知肚明。</p><p>就我所见，很少有哪行哪业能拥有一丁点自雇工作所带来的好处。</p><p>充足的休息、追求内在的目标层级、不用在人造蓝光前干坐8个小时、对精通的追求以及随之而来的深深满足感……好处不胜枚举。</p><p>为了赚取一份可预测的固定收入，人类的心理状况、整体健康，以及自我实现的<em>基本需求</em>，都被统统扫到了地毯下（视而不见）。</p><p>这毫无道理，因为优质的多巴胺来源于为自身生存而狩猎、追求<em>你</em>自己设定的目标、并在<em>你</em>选择的技能上达到精通——而不是某个主动提出牵着你的手走向他们目标的人。</p><p>你该如何预防或逃离这种现实？</p><p>获取技能、建立创造性的收入来源，并接纳自给自足的价值观。</p><p>但这还不是全部。</p><p><em>互联网已经拉平了竞争环境。</em></p><p>各种经验水平的人都在解决自己的问题，学习新技能，并以引人入胜的方式在网上发布他们的发现。</p><p>这可谓是一石四鸟。</p><ul><li>通过经验学习构建杠杆的技能（比如写作、说服力，以及其他伴随打造个人品牌而来的具有市场价值的技能）</li><li>建立数字杠杆（粉丝群体、人脉网络，以及永远存活于网上的数字资产）</li><li>研究他们真正想追求的兴趣（通过整理自己的想法并发布到网上来学习它们）</li><li>为那些比他们落后一两步的人提供帮助（因为人们正在对“体制”失去信任，更想从活生生的人那里学习）</li></ul><p>现代教育的现状正在我们眼前发生改变。</p><p>就像比特币一样，教育将继续去中心化。</p><p>创作者就是新的老师。</p><p>消费者就是新的学生。</p><h2 id="新教育系统" tabindex="-1">新教育系统 <a class="header-anchor" href="#新教育系统" aria-label="Permalink to &quot;新教育系统&quot;">​</a></h2><blockquote><p>现行的教育系统无法为你未来的工作做好准备。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1546816648199507969?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年7月12日</a></p></blockquote><p>实际上，我要教你的是一套旧的教育系统。</p><p>在政府支持的学校出现之前很久，我们是如何学习的？</p><p>向我们的父母、社区以及经验学习。</p><p>我们碰了火，哭了几分钟，然后明白了生活中蕴含着风险。有些风险是可控的，有些则是自我欺骗和幻象的产物。</p><p>作为没有既定道路可走的人类（并非为了完美契合我们所构建的社会），我们追随自己的好奇心，从经验中学习，并寻找能帮助我们在独特道路上加速前进的导师。</p><p>我们完全把一切都搞反了。</p><p>从小的时候起，我们就一直被条件反射般地规训去：</p><ul><li>取悦他人，并根据表现（而不是我们真正学到了什么）被评分</li><li>迎合社会的需求和欲望（因为接受别人的意识形态比创造自己的生活方式更容易）</li><li>限制我们自己的思想，以至于开始怀疑：“难道人生就只有这些了吗？”</li></ul><p>这是一场灾难。</p><p>去上学，做别人让你做的事，拿个学位，被训练去干一份可被替代的工作，拿着固定的收入，而这收入决定了你在社会中的价值……</p><p>什么都不准质疑，只看你眼前的东西，并且你休想比我更优秀！我嘴上说着一切都是为了你好……但这只不过是一个幌子，用来为我那些释放出相反信号的潜意识行为进行辩护。</p><p>新教育系统不依赖于社会。</p><p>它依赖于你。</p><p>自我教育才是答案，但没有人知道如何进行自我教育……而这恰恰就是问题的关键。</p><h2 id="将你的教育掌控在自己手中的5个步骤" tabindex="-1">将你的教育掌控在自己手中的5个步骤 <a class="header-anchor" href="#将你的教育掌控在自己手中的5个步骤" aria-label="Permalink to &quot;将你的教育掌控在自己手中的5个步骤&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>我们并未进入另一个文艺复兴时代。</p><p>观点、信息和建议无处不在。</p><p>人们正在对宗教、政府和被强加的意识形态失去信任。</p><p>这让我们处于一种长期的焦虑和不确定状态中。秩序已经丧失，我们的思想正遭受着反噬。</p><p>在过去，宗教教义和被广泛接受的文化标准给了我们一个可供追求的外在目标层级。它给我们的生活带来了秩序。我们不需要去<em>思考</em>未来会怎样。这既是祝福，也是诅咒。</p><p>现在，我们必须把事情掌握在自己手中。做法如下：</p><p><strong>1) 认识你自己</strong></p><blockquote><p>如果你不知道自己想要什么，那就弄清楚你不想要什么，然后朝着相反的方向努力。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1537030087874420738?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年6月15日</a></p></blockquote><p>你希望你的未来是什么样的？</p><p>你打算如何到达那里？目标是什么？</p><p>你为什么想到达那里？对你来说什么才是重要的？</p><p>在接下来的一周里，好好思考你的<a href="https://youtu.be/h8BrVhksQw8" target="_blank" rel="noreferrer">愿景、目标和价值观</a>。然后将以下这些后续步骤内化于心。</p><p><strong>2) 追随你的好奇心</strong></p><p>3件事：</p><ul><li>潜在的实用性</li><li>潜在的创造力</li><li>潜在的愉悦感</li></ul><p>这些是你在构建一项能盈利的技能栈时应当去寻找的东西。</p><p>没错，是技能<em>栈</em>（stack）。而不是单一的技能。</p><p>这正是大多数创意工作者犯错的地方。你不能整天只是埋头创作艺术，然后指望别人能像你一样欣赏它。</p><p>如果你想追求一门艺术技能，很好，去干吧，但你必须以开放的心态，用一种能帮助他人得到他们想要的东西的方式来提供这项技能。</p><p>写作、营销、销售。</p><p>去学这些。这能赋予你选择去学的任何其他技能以实用性。</p><p>愉悦感？那是在过程里产生的。多去尝试。把“屎”（sh*t）往墙上糊，看看哪块能粘住。</p><p><strong>3) 启动一个个人项目</strong></p><blockquote><p>你可以整天看书听建议，但除非你应用并体验这些教导，否则它们毫无意义。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1476483719653376003?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2021年12月30日</a></p></blockquote><p>项目拥有强大的力量。</p><p>首先，它们能让你摆脱“教程地狱”——那种让你产生自己正在进步的错觉、无休止的学习循环。</p><p>其次，它们迫使你去构建一些在现实世界中有实际作用的东西。</p><p>关键词是：<em>构建</em>（build）。</p><p>第三，它们教会你如何去追求优质多巴胺的来源。你可以取得进展、变得痴迷，并体验到所有伟大企业家都在谈论的那种能量。</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">写一份新闻简报（Newsletter）</a>，并发现你写作中的漏洞。</p><p>为你的品牌设计一张横幅（banner），从而迫使你去研究那些可用来制作这类图片的工具。</p><p>把你去年那个“价值百万美元”的App点子做出来。又不是说你不能在YouTube上搜索“如何开发一个App”，做些深挖，然后花上几个月时间真正去把它做出来。</p><p>别让你的大脑欺骗了你。</p><p><strong>4) 寻找特定的知识</strong></p><blockquote><p>先失败，再学习。\\</p><p>先行动，再提问。\\</p><p>先移动，再转向。\\</p><p>满满一箱油、地图上的路线，加上放在方向盘上的双手，如果你的脚不踩下油门，那只不过是一厢情愿罢了。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1561282467243466753?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年8月21日</a></p></blockquote><p>做项目会暴露出你所不知道的东西。</p><p>试图在开始前就学好一切，只会延误这个过程。</p><p>当你碰壁时，去寻找解决方案。</p><p>买一门课程、看一段YouTube视频、向你在社交媒体上关注的人问一个具体的问题、加入一个社群，总而言之……只要去参与那些讨论你兴趣的数字空间就好。</p><p>这就是这个“新教育系统”的美妙之处。</p><p>你不需要花费重金来获取你需要的答案。一切都在那里。人们只是不知道该搜索什么，因为他们还没有启动过项目，没有经历过失败，也没有被给予一个去搜索特定事物的理由。</p><p><em>创作者就是新的教授，但他们教授的信息，是那些老教授们直到下一次课程大纲更新之前都无法教授的</em>_._</p><p><strong>5) 将你的项目公之于众</strong></p><blockquote><p>“给我一个支点，一根足够长的杠杆，我就能撬动地球。”——阿基米德</p></blockquote><p>互联网赋予了任何人建立杠杆的机会。</p><ul><li>个人网站</li><li>在社交媒体上写作和进行教育</li><li>建立受众并接受付款</li><li>托管、管理和分发你的项目</li></ul><p>全世界的程序员们多年来一直在构建各种解决方案。</p><p>大多数人只要学会规则，参与游戏，并成为那个“在竞技场里拼搏的人”，他们就能做任何想做的事。</p><p>有一件事我想让你知道：</p><p>如果没有人支持你，你永远、永远、永远也无法靠做自己热爱的事赚到钱。</p><p>互联网让你能够接触到任何有Wi-Fi连接的人（前提是你要有策略，并且知道如何出现在他们面前）。</p><p>公开构建你的项目。谈论你的旅程。启发他人。并获取让它成功所必需的反馈。</p><p>（记住，没有反馈本身也是一种反馈。如果某条路走不通，显然，放弃并不是解决办法。）</p><p>我们下次见，朋友们。</p><p>— 丹·柯 (Dan Koe)</p><p><strong>本周动态</strong></p><p>《两小时写手》（The 2 Hour Writer）上线了！我们的首发非常棒，昨天有800多名学生获得了访问权限。今天早上开始涌入一些好评：</p><p><img src="'+a+'" alt=""></p><p><img src="'+o+'" alt=""></p><p><img src="'+l+'" alt=""></p><p>如果你想使用我的写作和内容系统，可以考虑去看看。</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">注册《两小时写手》（2 Hour Writer）。</a></p><p>在 Modern Mastery 中，个人品牌大师 <a href="https://twitter.com/sanathemonster" target="_blank" rel="noreferrer">Sana</a> 本人发布了《如何与顶尖创作者合作》（How To Collaborate With Top Creators），这是在社交媒体上成长并结识你所仰慕之人的关键。</p><p>本周三我们还安排了一场品牌研讨会。我们将拆解各个个人资料主页，并教你如何在网上最好地展示自己。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者只需支付5美元即可加入 MM。</a></p><p>一期关于我从零开始启动写作业务会采取的9个步骤的全新YouTube视频刚刚上线。</p><p><a href="https://youtu.be/N8U5bzSD65Q" target="_blank" rel="noreferrer">点击此处观看新视频。</a></p><hr><p><a href="/en/letters/how-to-get-what-you-want-out-of-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',113))])}const A=i(m,[["render",_]]);export{N as __pageData,A as default};
